package fpv.render;
import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.power.*;import fpv.construction.*;import java.util.*;
public final class PowerModelNativeTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static class Tex extends Texture{Tex(){super();width=height=64;}}
 static Block[] types(){return new Block[]{Blocks.powerNode,Blocks.powerNodeLarge,Blocks.surgeTower,Blocks.diode,Blocks.battery,Blocks.batteryLarge,Blocks.solarPanel,Blocks.largeSolarPanel,Blocks.combustionGenerator,Blocks.steamGenerator,Blocks.differentialGenerator,Blocks.rtgGenerator,Blocks.thoriumReactor,Blocks.impactReactor};}
 public static void main(String[] args)throws Exception{
  ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
  var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="chemical-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);

  Block[] types=types();int[] sizes={1,2,2,1,1,3,1,3,1,2,3,2,3,4};check(!PowerModelRenderer.supports(Blocks.thermalGenerator)&&!PowerModelRenderer.supports(Blocks.beamNode)&&!PowerModelRenderer.supports(Blocks.cryofluidMixer),"explicit 14-block scope; existing other models untouched");
  for(int i=0;i<types.length;i++){check(types[i].size==sizes[i],"installed native footprint");types[i].region=types[i].fullIcon=region;System.out.println("A2-16g native "+types[i].name+" size="+sizes[i]+" physicalHeight="+fpv.net.HeadlessGeometry.heightFor(types[i]));}
  ((PowerDiode)Blocks.diode).arrow=region;
  var renderer=new PowerModelRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=100;
  try{
   for(var p:PowerModelProfile.values())for(int lod=0;lod<3;lod++){var g=PowerModelGeometry.model(p,sizes[p.ordinal()],lod);check(g==PowerModelGeometry.model(p,sizes[p.ordinal()],lod),"immutable per-type templates shared");int count=0;for(var a:new float[][]{g.body(),g.lining(),g.rotor(),g.lights()}){count+=a.length/8;check(a.length%24==0,"triangles");for(int i=0;i<a.length;i+=8){for(int j=0;j<8;j++)check(Float.isFinite(a[i+j]),"finite local template");check(Math.abs(a[i])<=.501&&Math.abs(a[i+2])<=.501&&a[i+1]>=0&&a[i+1]<=1,"existing envelope");check(a[i+6]<0||a[i+6]<=1&&a[i+7]>=0&&a[i+7]<=1,"safe atlas UV");}}check(count<3500,"bounded geometry");}
   for(int floor:new int[]{0,1,3,4,5})for(int t=0;t<types.length;t++)for(int rotation=0;rotation<4;rotation++){
    var b=AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,12+rotation*24,10+t*5,floor,types[t],rotation);b.enabled=true;if(b.power!=null)b.power.status=.25f;if(b instanceof PowerGenerator.GeneratorBuild g)g.productionEfficiency=.7f;if(b instanceof ConsumeGenerator.ConsumeGeneratorBuild c){c.totalTime=19;c.warmup=.7f;}if(b instanceof ImpactReactor.ImpactReactorBuild c){c.totalProgress=19;c.warmup=.7f;}
    if(b instanceof Battery.BatteryBuild)check(PowerModelRenderer.level(b)==.25f,"real buffered status, not fabricated stored energy");if(b instanceof PowerGenerator.GeneratorBuild)check(PowerModelRenderer.level(b)==.7f,"real native production efficiency");
    float clock=PowerModelRenderer.clock(b);Time.time+=500;check(clock==PowerModelRenderer.clock(b),"global time cannot drive native machinery");
    for(float distance:new float[]{0,900,10000}){var before=LogisticsModelNativeTest.state(b);float status=b.power==null?0:b.power.status;int items=b.items==null?0:b.items.total();float h=fpv.net.HeadlessGeometry.heightFor(b.block),base=floor*1.4f;batch.clear();check(renderer.render(b,batch,0,base,0,b.block.size,h,distance),"all native XYZ/rotations/LOD");var v=LogisticsModelNativeTest.vertices(batch);for(int i=0;i<v.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(v[i+j]),"finite transformed stream");check(Math.abs(v[i])<=b.block.size*.501f&&Math.abs(v[i+2])<=b.block.size*.501f&&v[i+1]>=base-.00001f&&v[i+1]<=base+h+.01f,"no geometry outside original hitbox/physical height");check(v[i+7]>=0&&v[i+7]<=.5f&&v[i+8]>=0&&v[i+8]<=.5f,"native/white atlas UVs");}check(Arrays.equals(before,LogisticsModelNativeTest.state(b))&&clock==PowerModelRenderer.clock(b)&&status==(b.power==null?0:b.power.status)&&items==(b.items==null?0:b.items.total()),"no rendering mutation of fuel/coolant/charge/clocks/reactor state");}
    if(b instanceof PowerGenerator.GeneratorBuild){b.enabled=false;check(PowerModelRenderer.level(b)==0,"disabled generators do not claim production");b.enabled=true;((PowerGenerator.GeneratorBuild)b).productionEfficiency=0;check(PowerModelRenderer.level(b)==0,"idle/no output state");}
   }
   check(renderer.entries()==14&&renderer.builds()==14&&renderer.bytes()<2_000_000,"bounded cache reused by every instance/state");System.out.println("PowerModelNativeTest: "+checks+" installed models/XYZ/UV/LOD/charge/native clock/read-only checks PASS; mock GL, no physical acceptance");
  }finally{renderer.clear();batch.dispose();pix.dispose();}
 }
}
